function ending(){
 app.innerHTML=`<section class="card royal-ending"><div class="eyebrow">All ${cases.length} story cases completed</div><h1>A royal commendation,<br>${esc(state.playerName)}.</h1><p>The twelve visitors of Arcanexus Academy honor your care, clear words and patient support.</p><div id="certificate-preview" aria-label="Royal certificate for ${esc(state.playerName)}" aria-busy="true"><p>Illuminating your royal certificate…</p></div><p id="certificate-status" class="note" role="status"></p><div class="actions"><button id="certificate-png" disabled class="primary">Save PNG</button><button id="certificate-pdf" disabled>Save PDF</button><button id="endless-start" class="primary">${state.endless.active?'Continue endless request':'Enter Endless Support →'}</button><button id="ending-journal" class="quiet">Journal & practice</button><button id="ending-home" class="text-button">Title screen</button></div></section>`;
 document.querySelector('#endless-start').onclick=beginEndless;document.querySelector('#ending-journal').onclick=journal;document.querySelector('#ending-home').onclick=goHome;
 const preview=document.querySelector('#certificate-preview'),status=document.querySelector('#certificate-status');createCertificate(certificateSnapshot(),Object.keys(characterArt)).then(canvas=>{if(!preview.isConnected)return;canvas.setAttribute('role','img');canvas.setAttribute('aria-label',`Royal certificate for ${state.playerName}: ${state.completed.length} quests, ${state.stars} Magic Stars, ${state.xp} XP`);preview.replaceChildren(canvas);preview.setAttribute('aria-busy','false');for(const id of ['certificate-png','certificate-pdf'])document.querySelector('#'+id).disabled=false;document.querySelector('#certificate-png').onclick=()=>downloadCertificatePNG(canvas);document.querySelector('#certificate-pdf').onclick=()=>downloadCertificatePDF(canvas);}).catch(error=>{if(!preview.isConnected)return;preview.setAttribute('aria-busy','false');status.textContent=`Certificate could not load: ${error.message}. Your completed progress is saved; please reload to retry.`;});
}

function beginEndless(){resetTurn();replay=null;state=startEndless(state);persist();view='arrival';render();}
function goHome(){resetTurn();replay=null;state=returnToStory(state);persist();view='title';render();}
function navigationContext(){return `${state.caseIndex}:${state.mode}:${state.endless.completed}:${replay?.caseIndex??replay?.case?.id??'main'}`;}
function backPage(){
 stopMic();if(view==='profile'){state.playerName=document.querySelector('#player-name').value.trim().slice(0,32);persist();}
 const context=navigationContext();let target;
 while(screenHistory.length){const candidate=screenHistory.pop();if(replay&&candidate.context===`${state.caseIndex}:${state.mode}:${state.endless.completed}:main`&&['game','arrival','ending'].includes(candidate.view)){replay=null;state=returnToStory(state);target=candidate;break;}if(candidate.view==='title'||candidate.context===context){target=candidate;break;}}
 if(!target){if(replay){goingBack=true;continueStory();return;}target={view:'title',introPage:0};}
 goingBack=true;result=null;transcriptPending=false;selectedChoice=null;view=target.view;introPage=target.introPage;
 if(view==='reward'){if(target.reward)reward=target.reward;else view='title';}
 persist();render();
}
function render(){const screen={view,introPage,context:navigationContext(),reward};const changed=lastScreen&&(lastScreen.view!==view||lastScreen.introPage!==introPage||lastScreen.context!==screen.context);if(changed&&!goingBack){screenHistory.push(lastScreen);if(screenHistory.length>40)screenHistory.shift();}goingBack=false;lastScreen=screen;document.querySelector('#back-page').hidden=view==='title';applySettings();document.querySelector('#toolbar').hidden=['title','profile','intro'].includes(view);({title,profile,intro,arrival,game,reward:completed,ending}[view])();renderPlayerStatus();mountCharacter(document.querySelector('#character-stage'),currentCase()?.character,mood);if(assetFailure)app.insertAdjacentHTML('afterbegin','<p class="asset-warning" role="status">Cinematic artwork could not load. You can still play the text-based activities. Reload to retry the images.</p>');}
function showModal(title,html){stopMic();content.innerHTML=`<h2>${title}</h2>${html}`;if(!modal.open)modal.showModal();}
function journal(){const e=state.endless;const glossary=new Map([...cases.flatMap(c=>c.vocabulary||[]),...templates.flatMap(t=>t.vocabulary)]);showModal('ARCANEXUS ACADEMY · Your chamber journal',`<div class="rewards"><div class="stat">Story progress<strong>${state.completed.length}/${cases.length}</strong></div><div class="stat">Magic Stars<strong>${state.stars}</strong></div><div class="stat">Experience<strong>${state.xp} XP</strong></div><div class="stat">Satisfaction<strong>${storyAverage()}%</strong></div></div><details open><summary>Endless Support statistics</summary><p>${e.completed} requests resolved · ${e.seenTemplates.length}/${templates.length} templates practiced · ${e.totalScore} practice points · best score ${e.bestScore}/100 · average ${e.completed?Math.round(e.totalScore/e.completed):0}/100</p><p class="note">Story rewards never repeat. Endless points and friendships are tracked separately. All ${templates.length} templates are used before the next shuffled cycle.</p>${state.caseIndex>=cases.length?'<button id="journal-endless" class="primary">Enter Endless Support</button>':'<p class="note">Complete the four story chapters to unlock Endless Support.</p>'}</details><details><summary>Team Talk practice</summary><p>Practice Sprint Planning, Code Review, Asking for Help, Blockers, and advice to a teammate. Practice scores do not duplicate story rewards.</p>${teamTemplates.map(t=>`<div class="case-row"><strong>${esc(t.title)}</strong><p>${esc(t.problem)}</p><button data-team="${t.id}">Practice Team Talk</button></div>`).join('')}</details><details><summary>Meet the academy · friendship journal</summary><div class="roster">${Object.entries(characters).map(([id,p])=>`<article class="roster-card">${portrait(id,true)}<h3>${p.name}</h3><p>${p.role}</p><p>${p.personality}</p><p>${p.specialty}</p><p>Story friendship: ${state.hearts[id]||0}<br>Endless friendship: ${e.friendships[id]||0}</p></article>`).join('')}</div></details><details><summary>Achievements · ${state.achievements.length}</summary><p>${state.achievements.length?state.achievements.map(esc).join(' · '):'Your first achievement is waiting at the chamber.'}</p></details><details><summary>Vocabulary journal · ${state.vocabulary.length} learned terms</summary><div class="vocabulary-list">${state.vocabulary.length?state.vocabulary.map(term=>`<div><strong>${esc(term)}</strong><br>${esc(glossary.get(term)||'A technical term practiced in a support conversation.')}</div>`).join(''):'Complete a support case to collect its vocabulary.'}</div></details><details><summary>Story tickets · practice completed cases</summary><div class="case-list">${cases.map((c,i)=>`<div class="case-row"><strong>${i+1}. ${esc(c.title)}</strong>${state.completed.includes(i)?`<p>${starDisplay(state.questResults[i].bestScore)} · Best ${state.questResults[i].bestScore}/100</p>`:''}<div class="note">Chapter ${Math.floor(i/3)+1} · ${characters[c.character].name} · ${state.completed.includes(i)?'Resolved':i===state.caseIndex?'Available':'Locked'}</div>${state.completed.includes(i)?`<button data-replay="${i}">Practice this case</button>`:''}</div>`).join('')}</div></details>`);
 content.querySelectorAll('[data-team]').forEach(button=>button.onclick=()=>{resetTurn();replay={case:materialize(button.dataset.team,0,1),stepIndex:0,turnScores:[],draft:'',attempts:0};view='arrival';modal.close();render();});
 const endlessButton=document.querySelector('#journal-endless');if(endlessButton)endlessButton.onclick=()=>{modal.close();beginEndless();};content.querySelectorAll('[data-replay]').forEach(b=>b.onclick=()=>{replayQuest(Number(b.dataset.replay));});
}
function help(){showModal('How to Play',`<p>You are the Magical IT Advisor, working in the Magical Technology Support Chamber. Students and staff bring technical problems; your task is to listen and help in English.</p><ol><li>Read the visitor’s story and the goal for your turn.</li><li>Type a clear, polite response. Or choose Speak, start the microphone, review and edit the transcript, and confirm it before submitting.</li><li>Read the explanatory feedback. You can retry, request a Hint, or use Build a phrase when the rules do not recognize your wording.</li><li>Continue after a helpful response. Five turns—welcome, investigate, troubleshoot, explain, close—resolve a case.</li><li>Earn stars, experience, friendship, and achievements through four story chapters. Then enter Endless Support for ongoing practice.</li></ol><p>Before entering, choose an advisor name. The left sidebar shows your level (one level per 200 XP), carried-forward points, best quest scores, and Music controls. Open Quests to see the current visitor and who comes next. Completed quests have 1–5 star ratings; the replay dropdown lets you improve your best score while keeping your current story position. Every accepted reply adds its score to your carried-forward points, including replays and Team Talk. XP and story rewards are awarded only once.</p><p>Four learning tiers recognize Professional, Polite, Direct, and Growing skill responses. A relevant MCQ answer with a minor communication error can earn 35 points and continue with a correction. Unsafe or insulting answers receive no credit and require another attempt. Three model replies are available in the feedback.</p><p>Ctrl/Command + Enter submits. Your browser saves progress automatically on this device. Practice replay does not award story rewards again. Endless points and friendships have their own statistics.</p><p>Endless requests reuse ${templates.length} authored templates with shuffled order, varied context, and increasing difficulty. Advanced advice asks you to explain a purpose. The game does not generate new content with an AI model.</p><p>Choose mode offers four responses with contrasting tone, grammar, and technical suitability. The best response uses appropriate functional language and a safe, specific action with a reason. Type and Speak use exactly the same text evaluator.</p><p>Support conversations practice “Could you please + base verb”, “Would you mind + -ing”, “May I suggest”, “I’d be happy to help”, “We could”, and “Shall we”. Journal → Team Talk offers five software-team situations, including respectful disagreement followed by an alternative.</p><p>Transparent rules check intent terms, IT vocabulary, politeness, and sentence length. They do not fully assess grammar, semantic meaning, or pronunciation. Guided phrases offer a reliable fallback when a valid reply is missed.</p><p>Speech support varies by browser. HTTPS, permission, and the browser provider’s online service may be needed. The game does not store audio. Every case can be completed by typing.</p><p class="note">Visuals use generated cinematic 3D-style rendered illustrations with CSS effects, not real-time 3D.</p>`);}
function settings(){showModal('Settings',`<div class="settings-row"><label><input type="checkbox" id="motion" ${state.settings.motion?'checked':''}> Gentle magical effects</label></div><div class="settings-row"><label><input type="checkbox" id="large" ${state.settings.largeText?'checked':''}> Larger reading text</label></div><div class="settings-row"><label><input type="checkbox" id="music-enabled" ${state.settings.music?'checked':''}> Magical instrumental music</label></div><div class="settings-row"><label for="music-volume">Music volume</label><input id="music-volume" type="range" min="0" max="100" value="${Math.round(state.settings.musicVolume*100)}"><output id="volume-output">${Math.round(state.settings.musicVolume*100)}%</output></div><p class="note">Music is composed and synthesized locally, with no lyrics. It pauses while using the microphone or when the tab is hidden. Reduced-motion preferences are respected.</p><button id="reset-save">Reset saved progress</button><div id="reset-warning"></div><details><summary>Credits & responsible AI use</summary><p>OpenAI Codex assisted with code, authored dialogue, and automated tests. OpenAI image generation produced the original cinematic chamber and twelve separate transparent character illustrations, compressed to WebP for the game. These are rendered illustrations; there is no real-time 3D engine.</p><p>The runtime evaluator and case selection are JavaScript rules with no paid API, backend, or language model. Browser speech recognition may process audio through its provider. Human classroom review and real microphone testing remain necessary; no user-study results are claimed.</p><p>Team names, student IDs, and actual contributions must be completed by the team in GAME_DOCUMENT.md.</p></details>`);
 document.querySelector('#music-enabled').onchange=e=>{state.settings.music=e.target.checked;music.configure({enabled:state.settings.music});if(state.settings.music)music.start();persist();renderPlayerStatus();};document.querySelector('#music-volume').oninput=e=>{state.settings.musicVolume=Number(e.target.value)/100;music.configure({volume:state.settings.musicVolume});document.querySelector('#volume-output').textContent=e.target.value+'%';persist();};
 document.querySelector('#motion').onchange=e=>{state.settings.motion=e.target.checked;applySettings();persist();};document.querySelector('#large').onchange=e=>{state.settings.largeText=e.target.checked;applySettings();persist();};document.querySelector('#reset-save').onclick=()=>{document.querySelector('#reset-warning').innerHTML='<p>This replaces all story and endless progress on this device. Are you sure?</p><button id="do-reset">Yes, reset progress</button>';document.querySelector('#do-reset').onclick=()=>{try{closeJourney(storage,state,Object.keys(characterArt));}catch(error){document.querySelector('#reset-warning').textContent=`History could not be saved: ${error.message}`;return;}music.pause();resetTurn();replay=null;state={...freshState(),settings:{...state.settings}};persist();modal.close();view='title';render();};};
}
async function record(){
 if(result?.pass)return;
 if(listening){recognition?.stop();return;}
 const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;const status=document.querySelector('#speech-status');
 if(!Speech){status.textContent='This browser does not support speech recognition. Switch to Type mode to continue.';return;}
 if(!window.isSecureContext){status.textContent='Microphone input requires HTTPS or a trusted local development origin. Use Type mode here.';return;}
 recognition=new Speech();recognition.lang='en-US';recognition.interimResults=false;recognition.continuous=false;const active=recognition;
 recognition.onstart=()=>{listening=true;document.querySelector('#record').textContent='Stop listening';status.textContent='Listening in English… Speak one response. Audio may be processed by your browser’s speech provider.';};
 recognition.onresult=e=>{if(active!==recognition)return;const text=e.results[0][0].transcript;const answer=document.querySelector('#answer');if(!answer)return;answer.value=text;cursor().draft=text;transcriptPending=true;document.querySelector('#confirm-transcript').hidden=false;status.textContent='Review and edit the transcript. Stop listening, then press Use this transcript.';persist();};
 recognition.onerror=e=>{if(active!==recognition)return;music.setDucked(false);listening=false;const button=document.querySelector('#record');if(button)button.textContent='Start microphone';status.textContent=({'not-allowed':'Microphone permission was denied. Allow it in browser settings or use Type mode.','audio-capture':'No working microphone was found. Use Type mode.','no-speech':'No speech was detected. Try again or type your response.','network':'The browser speech service is unavailable. Use Type mode.','service-not-allowed':'The browser speech service is disabled. Use Type mode.','aborted':'Listening stopped.'}[e.error]||'Speech recognition failed. Please try again or use Type mode.');};
 recognition.onend=()=>{if(active!==recognition)return;music.setDucked(false);listening=false;const button=document.querySelector('#record');if(button)button.textContent='Start microphone';};
 try{await music.setDucked(true);if(active!==recognition||mode!=='speak'){music.setDucked(false);return;}recognition.start();}catch{music.setDucked(false);status.textContent='Could not start speech recognition. Try again or use Type mode.';listening=false;}
}
document.querySelector('#close-modal').onclick=()=>modal.close();
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
document.querySelector('#back-page').onclick=backPage;
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>({journal,settings,history:journeyHistory,home:goHome,'player-profile':playerProfile}[b.dataset.action])());
document.addEventListener('visibilitychange',()=>music.setVisible(!document.hidden));
window.addEventListener('pagehide',()=>{music.setVisible(false);stopMic();persist();});
window.addEventListener('pageshow',()=>music.setVisible(!document.hidden));
async function boot(){
 const files=['./assets/chamber.webp',...Object.values(characterArt).map(a=>a.src)];let loaded=0;
 const outcomes=await Promise.all(files.map(src=>new Promise(resolve=>{const image=new Image();const timer=setTimeout(()=>resolve(false),15000);image.onload=()=>{clearTimeout(timer);loaded++;document.querySelector('#loading-status').textContent=`Gathering light and portraits… ${loaded}/${files.length}`;resolve(true);};image.onerror=()=>{clearTimeout(timer);resolve(false);};image.src=src;})));
 assetFailure=outcomes.some(ok=>!ok);document.querySelector('#loading').hidden=true;persist();render();
}
applySettings();
boot();
